-- Kromi Connect: importación histórica de solicitudes del Excel de Diseño.
-- Ejecutar en Supabase SQL Editor. No crea ni modifica registros operativos.
-- Idempotente por (import_batch, source_row_number). Los datos originales se conservan en raw_payload.
-- IMPORTANTE: la tabla no aparecerá sola en la pestaña Historial; el frontend debe consultar esta tabla
-- y combinar sus filas con el historial operativo actual. Ver matriz de mapeo entregada junto al script.

begin;

create table if not exists public.design_solicitudes_historicas (
  id bigint generated by default as identity primary key,
  import_batch text not null,
  source_row_number integer not null,
  title text not null,
  source_timestamp timestamp without time zone,
  due_date date,
  objective text,
  publication_request text,
  designer_name_raw text,
  requester_name_raw text,
  priority_raw text,
  status_raw text,
  completed_at timestamp without time zone,
  department_raw text,
  reference_url text,
  print_request text,
  area_raw text,
  design_quantity_raw text,
  medium_raw text,
  requester_email text,
  pieces_quantity_raw text,
  publication_details_2 text,
  print_details_2 text,
  material text,
  dimensions text,
  review_required boolean not null default false,
  review_reasons text[] not null default '{}',
  raw_payload jsonb not null,
  imported_at timestamptz not null default now(),
  unique (import_batch, source_row_number)
);
create index if not exists design_solicitudes_historicas_history_idx on public.design_solicitudes_historicas (source_timestamp desc nulls last, due_date desc nulls last);
alter table public.design_solicitudes_historicas enable row level security;
revoke all on table public.design_solicitudes_historicas from anon, authenticated;
grant select on table public.design_solicitudes_historicas to authenticated;
drop policy if exists design_solicitudes_historicas_design_read on public.design_solicitudes_historicas;
create policy design_solicitudes_historicas_design_read
  on public.design_solicitudes_historicas
  for select to authenticated
  using ((select public.has_permission('design.requests.read')));
-- Solo el editor SQL/administrador importa; los clientes autenticados tienen SELECT únicamente.
-- Se conserva el estado legado tal como está; no se traduce a estados operativos.

insert into public.design_solicitudes_historicas (import_batch, source_row_number, title, source_timestamp, due_date, objective, publication_request, designer_name_raw, requester_name_raw, priority_raw, status_raw, completed_at, department_raw, reference_url, print_request, area_raw, design_quantity_raw, medium_raw, requester_email, pieces_quantity_raw, publication_details_2, print_details_2, material, dimensions, review_required, review_reasons, raw_payload)
