on conflict (import_batch, source_row_number) do update set
  title = excluded.title,
  source_timestamp = excluded.source_timestamp,
  due_date = excluded.due_date,
  objective = excluded.objective,
  publication_request = excluded.publication_request,
  designer_name_raw = excluded.designer_name_raw,
  requester_name_raw = excluded.requester_name_raw,
  priority_raw = excluded.priority_raw,
  status_raw = excluded.status_raw,
  completed_at = excluded.completed_at,
  department_raw = excluded.department_raw,
  reference_url = excluded.reference_url,
  print_request = excluded.print_request,
  area_raw = excluded.area_raw,
  design_quantity_raw = excluded.design_quantity_raw,
  medium_raw = excluded.medium_raw,
  requester_email = excluded.requester_email,
  pieces_quantity_raw = excluded.pieces_quantity_raw,
  publication_details_2 = excluded.publication_details_2,
  print_details_2 = excluded.print_details_2,
  material = excluded.material,
  dimensions = excluded.dimensions,
  review_required = excluded.review_required,
  review_reasons = excluded.review_reasons,
  raw_payload = excluded.raw_payload,
  imported_at = now();

-- Verificación posterior: conteo importado por lote y filas que requieren revisión.
select import_batch, count(*) as total_importado,
       count(*) filter (where review_required) as requieren_revision
from public.design_solicitudes_historicas
where import_batch = 'excel_solicitudes_diseno_20261026'
group by import_batch;
select source_row_number, title, status_raw, review_reasons
from public.design_solicitudes_historicas
where import_batch = 'excel_solicitudes_diseno_20261026' and review_required
order by source_row_number;
commit;
